declare const tools: { mcp__pixellab__create_image_pro(args: {
  // What to draw (e.g. 'ornate iron key with a ruby inlay').
  description: string;
  // Canvas height. Max depends on aspect ratio (see width).
  height?: number;
  // At most this many colours in each image; with a palette, picked from it.
  max_colors?: number | null;
  // Transparent background (the default, for assets). False for scenes and backdrops.
  no_background?: boolean;
  // 2 to 256 hex colours, e.g. ["#081820", "#346856", "#88c070", "#e0f8d0"] for Game Boy; every pixel of the result is one of them.
  palette?: Array<string> | null;
  // Names the palette, e.g. 'Game Boy'; helps the look. Needs palette.
  palette_name?: string | null;
  // Internal Game Builder project context; the finished image is linked after generation.
  project_id?: string | null;
  // Up to 4 labelled images, a JSON array of {"url" (preferred) or "base64", "usage"}, e.g. [{"url": "https://...", "usage": "outfit and armour"}]. "usage" says what to take from each. A "url" may be https, data: or an `upload:<id>` from get_upload_url.
  reference_images?: Array<{ [key: string]: unknown; }> | null;
  // Seed for reproducible generation.
  seed?: number | null;
  // Any of color_palette, outline, detail, shading to take from the style image (needs one). Default all four; with a palette, all but color_palette, which is then refused.
  style_copy?: Array<string> | null;
  // An image whose art style (palette, outline, detail, shading) the result matches; style_copy narrows which.
  style_image_base64?: string | null;
  // https, data: or `upload:<id>` URL instead of style_image_base64; prefer it. Give one, not both.
  style_image_url?: string | null;
  // Canvas width. The cap is an area of about a quarter megapixel by nearest aspect ratio: 512x512 square, 688x384 at 16:9, 792x336 the widest. Larger is refused before queueing.
  width?: number;
}): Promise<CallToolResult>; };
```"},{"name":"mcp__pixellab__create_image_pro_flash","description":"Create one Pro Flash pixel-art image with an optional left-box style image.

